   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

let slider;
let phase = 1;
let zoff = 1;
let angle =0;
var seed = Math.random() * 1000;
let colors1 = "e3d7a3BF-f5989d33-ea618e40-fce4d6b3-caac7180".split("-").map((a) => "#" + a);
let colors2 = "6cbbd4BF-5863b140-5282a1BF-fee8f733-c1f29b80".split("-").map((a) => "#" + a);
let colors3 = "1b1b1bBF-29292940-f3f3f3BF-222222b3-ff000080".split("-").map((a) => "#" + a);
let colors4 = "70c1b3BF-aaf0d340-50514f33-ffe066b3-247ba080".split("-").map((a) => "#" + a);
let colors5 = "3c1642BF-38637540-08637533-b2ff9eb3-1dd3b080".split("-").map((a) => "#" + a);
let colorbg = "fbf8ef".split("-").map((a) => "#" + a);
let colorbg2 = "fbf8ef03".split("-").map((a) => "#" + a);
var color1, color2;
var mySize;

function setup() {
	randomSeed(seed);
  createCanvas(windowWidth, windowHeight);
	mySize = max(windowWidth, windowHeight);
  // pixelDensity(5);
  background(colorbg);
  slider = random(1.5, 2.5);
	color1 = random([colors1,colors2,colors3,colors4,colors5]);
	color2 = random([colors1,colors2,colors3,colors4,colors5]);
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

	randomSeed(seed);
  background(colorbg);
  translate(width / 2, height / 2);
  let gap = 0.01;
  for (var i = 0; i < 100; i++) {
    let noiseMax = slider; 
    for (var a = 0; a < random(0,PI); a += 0.05) {
			noFill();
      stroke(random(color1));
      rotate(random(HALF_PI)+angle);
      let xoff = map(cos(a + phase), -1, 1, 0, noiseMax);
      let yoff = map(sin(a + phase / 2), -1, 1, 0, noiseMax);
      let r = map(noise(xoff, yoff, zoff), 0, 1, 100, mySize*0.75) * i * gap;
      let x = r * cos(a);
      let y = r * sin(a);
			strokeWeight(random(5));
			rectMode(CENTER);
      circle(x, y,random(15));
			strokeWeight(random(2));
			line(0,0,x,y);
    }
     slider += 0.001;
  }

  phase += random(0.005);
  zoff += random(0.005);
	angle +=PI/360/1000 ;
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("NoiseWaves_04", "png");
	}
}

//fullscreen
function mousePressed() {
  if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) {
		noCursor();
    let fs = fullscreen();
    fullscreen(!fs);
  }
}

